import '../models/catalog.dart';
import '../services/app_state.dart';
import '../theme.dart';
import 'cart_screen.dart';
class RestaurantMenu extends StatelessWidget{final Restaurant restaurant;const RestaurantMenu({super.key,required this.restaurant});@override Widget build(BuildContext context){final s=AppState.instance;return Scaffold(appBar:AppBar(title:Text(restaurant.name,style:const TextStyle(fontWeight:FontWeight.w900)),actions:[IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const CartScreen())),icon:const Icon(Icons.shopping_bag_outlined))]),body:ListView(padding:const EdgeInsets.all(18),children:[Container(height:155,decoration:BoxDecoration(borderRadius:BorderRadius.circular(28),gradient:const LinearGradient(colors:[Color(0xFF6C4CF1),Color(0xFF14B8A6)])),child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisAlignment:MainAxisAlignment.end,children:[Text(restaurant.name,style:const TextStyle(color:Colors.white,fontSize:25,fontWeight:FontWeight.w900)),Text('${restaurant.category} • ⭐ ${restaurant.rating} • ${restaurant.eta} دقيقة',style:const TextStyle(color:Colors.white70))]))),const SizedBox(height:18),...restaurant.menu.map((m)=>Card(margin:const EdgeInsets.only(bottom:10),child:ListTile(contentPadding:const EdgeInsets.all(12),title:Text(m.name,style:const TextStyle(fontWeight:FontWeight.w900)),subtitle:Padding(padding:const EdgeInsets.only(top:5),child:Text(m.description)),trailing:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text('${m.price.toStringAsFixed(0)} ج.م',style:const TextStyle(fontWeight:FontWeight.w900)),const SizedBox(height:4),SizedBox(height:34,child:FilledButton(onPressed:(){s.add(m);ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تمت إضافة المنتج للسلة')));},child:const Text('إضافة')))]))),)]);}}
